  "layers/core/server/utils/http-error.ts": "// Generated by bildr. Editing this file detaches it from the editor.\nimport { createError } from 'nuxt/server'\nimport type { DomainError, ErrorStatusMap, Result } from '#core/kernel/result'\n\n/** HTTP adapter for use-case results: return the value, or throw the domain error as an HTTP error. */\nexport const unwrapOrThrow = <T, E extends DomainError>(result: Result<T, E>, statuses: ErrorStatusMap): T => {\n  if (result.ok) return result.value\n  throw createError({\n    status: statuses[result.error.type] ?? 400, // unknown types become 400\n    message: result.error.message,\n    data: result.error\n  })\n}\n\nexport const notFound = (message: string) => createError({ status: 404, message })\n",
  "layers/core/server/utils/remote.ts": "// Generated by bildr. Editing this file detaches it from the editor.\nimport { createError, useRuntimeConfig } from 'nuxt/server'\nimport { HttpFailure, createHttpClient } from '#core/http/client'\n\n/** One call to a REST data source. A `body` is sent as JSON; with `optional`, a 404 resolves to undefined. */\nexport interface RemoteRequest {\n  method?: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE'\n  query?: Record<string, string | number | boolean | undefined>\n  body?: unknown\n  optional?: boolean\n}\n\n/** A minimal HTTP client port for REST data sources, so repositories can be tested with a fake. An empty answer resolves to undefined. */\nexport type RemoteClient = <T>(path: string, options?: RemoteRequest) => Promise<T>\n\ntype DataSourceName = keyof ReturnType<typeof useRuntimeConfig>['datasources']\n\n/** A REST client for a named data source, over the core HTTP client. Base URL and credentials come from runtimeConfig (env), never from the model. */\nexport const useRemote = (name: DataSourceName): RemoteClient => {\n  const { baseUrl, apiKey } = useRuntimeConfig().datasources[name]\n  const headers: Record<string, string> = { accept: 'application/json' }\n  if (apiKey) headers.authorization = `Bearer ${apiKey}`\n  const call = createHttpClient({ baseUrl, headers })\n\n  return async <T>(path: string, options?: RemoteRequest) => {\n    try {\n      return await call(path, { method: options?.method ?? 'GET', query: options?.query, body: options?.body }) as T\n    } catch (cause) {\n      if (!(cause instanceof HttpFailure)) throw cause\n      if (options?.optional && cause.status === 404) return undefined as T\n      throw createError({ status: 502, message: `Data source \"${String(name)}\" ${cause.message}.` })\n    }\n  }\n}\n",
